import { t } from '../../core/i18n.992e75b62dfb.mjs';
const safeItem = (item, memory = false) => Object.freeze({ id: String(item.id), content: item.sensitive ? '[redacted]' : String(item.content ?? ''), provenance: item.provenance ?? 'unknown', confidence: item.confidence ?? null, scope: item.scope ?? 'unknown', freshness: item.freshness ?? 'unknown', actions: Object.freeze(memory ? ['pin', 'exclude', 'edit', 'delete'] : ['pin', 'exclude']) });
export function buildContextMemoryView({ context = [], memories = [], conflicts = [], retention = {} } = {}) { return Object.freeze({ context: Object.freeze(context.map((item) => safeItem(item))), memories: Object.freeze(memories.map((item) => safeItem(item, true))), conflicts: Object.freeze(conflicts.map((item) => Object.freeze({ ...item }))), retention: Object.freeze({ ...retention }) }); }
export function renderContextMemoryView(value, { language = 'en' } = {}) { return `<section><h1>${t('control.domain.context-memory', language)}</h1><p>${value.context.length} ${t('control.contextItems', language)} · ${value.memories.length} ${t('control.memories', language)}</p></section>`; }
